cd "$PWD" && python3 - <<'PY'
from units import convert
L = ["m","km","cm","mi","ft","in"]; M = ["kg","g","lb","oz"]; T = ["C","F","K"]
for a in L:
    for b in L: convert(3.7, a, b)
for a in M:
    for b in M: convert(3.7, a, b)
for a in T:
    for b in T: convert(300, a, b)
print("all pairs ok")
print(convert(1,"oz","lb"), convert(1,"lb","oz"), convert(0,"C","K"), convert(0,"K","F"))
print(convert(-459.67,"F","K"), abs(convert(-40,"C","F")+40) < 1e-9)
for bad in [(-273.16,"C"),(-459.68,"F"),(-1,"K")]:
    try: convert(bad[0], bad[1], "K")
    except ValueError as e: print("ok:", e)
for args in [("m","kg"),("m","x"),("x","m")]:
    try: convert(1,*args)
    except ValueError as e: print("ok:", e)
print(convert("2","km","m"), type(convert(1,"km","m")))
PY

